mapper.select:
SELECT id, type_code AS typeCode, type_name AS typeName, type_category AS typeCategory, CASE type_category WHEN 'sensor' THEN '传感器' WHEN 'controller' THEN '控制器' WHEN 'gateway' THEN '网关' ELSE '其他' END AS typeCategoryText, icon, protocol, manufacturer, model, spec_json AS specJson, status, CASE status WHEN 1 THEN '正常' ELSE '禁用' END AS statusText, create_by AS createBy, create_time AS createTime FROM agri_iot_device_type WHERE del_flag = 0
AND type_code LIKE CONCAT('%', #{dto.typeCode}, '%')
AND type_name LIKE CONCAT('%', #{dto.typeName}, '%')
AND type_category = #{dto.typeCategory}
AND status = #{dto.status}
ORDER BY create_time DESC LIMIT #{dto.pageNum}, #{dto.pageSize}

SELECT COUNT(*) FROM agri_iot_device_type WHERE del_flag = 0
AND type_code LIKE CONCAT('%', #{dto.typeCode}, '%')
AND type_name LIKE CONCAT('%', #{dto.typeName}, '%')
AND type_category = #{dto.typeCategory}
AND status = #{dto.status}
